<template>
  <main class="prep-page" aria-labelledby="prep-title">
    <header class="prep-header">
      <div><p class="prep-eyebrow">YOUR STUDY COMPANION <span> / </span> TEXT CHAT</p><h1 id="prep-title">A little guidance, whenever you need it.</h1><p>Ask about your preparation, work through a question, or make a plan that fits your goals.</p></div>
      <div class="prep-header-mark" aria-hidden="true"><svg viewBox="0 0 64 64" fill="none"><path d="M13 14h38v27H30L19 50v-9h-6z" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/><path d="M23 25h18M23 32h12" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></div>
    </header>
    <div class="prep-layout">
      <aside class="prep-guide" aria-label="Study chat settings">
        <div class="prep-guide-top"><span class="prep-badge">STUDY SPACE</span><h2>Make progress one question at a time.</h2><p>Talk through a challenge or get a practical next step for your preparation.</p></div>
        <div class="prep-divider"></div>
        <label for="prep-exam">Your exam</label>
        <select id="prep-exam" v-model="exam" :disabled="busy"><option value="ielts">IELTS Speaking</option><option value="toefl">TOEFL Speaking</option></select>
        <div class="prep-guide-note"><span class="prep-guide-icon" aria-hidden="true">i</span><p>Responses are generated by the configured online model and are practice guidance, not official exam scores.</p></div>
        <button class="prep-new" type="button" @click="newChat" :disabled="!messages.length && !draft"><span aria-hidden="true">+</span> New conversation</button>
      </aside>
      <section class="prep-chat" aria-label="Preparation conversation">
        <div class="prep-chat-head"><div class="prep-avatar" aria-hidden="true">P<span>.</span></div><div><h2>Prep assistant</h2><p><span class="prep-online-dot" aria-hidden="true"></span> Here to help you prepare</p></div><span class="prep-chip">{{ exam === 'ielts' ? 'IELTS' : 'TOEFL' }}</span></div>
        <div ref="scroll" class="prep-scroll" role="log" aria-label="Conversation messages" aria-live="polite" aria-relevant="additions text">
          <div v-if="!messages.length" class="prep-welcome">
            <div class="prep-spark" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none"><path d="M16 3l2.7 8.3L27 14l-8.3 2.7L16 25l-2.7-8.3L5 14l8.3-2.7L16 3z" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/></svg></div>
            <p class="prep-eyebrow">LET'S GET YOU STARTED</p><h3>What would you like to work on?</h3><p>Ask anything about speaking practice, preparation strategies, or your next study session.</p>
            <div class="prep-prompts"><button v-for="item in prompts" :key="item.title" type="button" @click="usePrompt(item.text)"><span>{{ item.title }}</span><small>{{ item.subtitle }}</small><span class="prep-prompt-arrow" aria-hidden="true">↗</span></button></div>
          </div>
          <article v-for="(item,index) in messages" :key="item.id" class="prep-message" :class="'prep-message--'+item.role"><div class="prep-message-avatar" aria-hidden="true">{{ item.role === 'user' ? 'Y' : 'P' }}</div><div class="prep-message-content"><div class="prep-message-meta">{{ item.role === 'user' ? 'You' : 'Prep assistant' }}</div><div v-if="item.role === 'assistant'" class="prep-message-text prep-markdown" v-html="renderMarkdown(item.content)"></div><div v-else class="prep-message-text">{{ item.content }}</div><span v-if="failed && index === messages.length - 1 && item.role === 'user'" class="prep-not-sent">Awaiting a response</span></div></article>
          <div v-if="busy" class="prep-typing" role="status"><span class="prep-message-avatar" aria-hidden="true">P</span><span>Thinking through your question<span class="prep-typing-dots" aria-hidden="true"> ···</span></span></div>
          <div v-if="error && !busy" class="prep-error" role="alert"><div><strong>Could not get a response</strong><p>{{ error }}</p></div><div class="prep-error-actions"><button type="button" @click="retry">Try again</button><button type="button" @click="editFailed">Edit message</button></div></div>
        </div>
        <form class="prep-composer" @submit.prevent="send">
          <label for="prep-input">Your question</label><textarea id="prep-input" ref="input" v-model="draft" :disabled="busy || failed" maxlength="4000" rows="3" placeholder="Ask a question about preparing for your speaking test…" @keydown="onKeydown"></textarea>
          <div class="prep-composer-bottom"><p><span>Enter to send</span> · Shift + Enter for a new line</p><button type="submit" :disabled="busy || failed || !draft.trim()">{{ busy ? 'Sending…' : 'Send message' }} <svg aria-hidden="true" viewBox="0 0 20 20" fill="none"><path d="M4 10h11m-4-4 4 4-4 4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></button></div>
          <p class="prep-privacy">Your message is sent to your configured cloud provider. This conversation is kept in this page session.</p>
        </form>
      </section>
    </div>
  </main>
</template>

<script>
import MarkdownIt from 'markdown-it'
import DOMPurify from 'dompurify'

const markdown = new MarkdownIt({ html: false, linkify: true, breaks: true }).disable('image')

export default {
  name: 'PrepChat',
  data () { return { exam: 'ielts', draft: '', messages: [], busy: false, failed: false, error: '', sequence: 0, activeRequest: null, prompts: [
    { title: 'Build a study plan', subtitle: 'A practical routine for my goals', text: 'Help me make a realistic speaking preparation plan for the next two weeks.' },
    { title: 'Practise an answer', subtitle: 'Structure ideas with confidence', text: 'How can I structure a clear answer when I do not know much about the topic?' },
    { title: 'Improve my fluency', subtitle: 'Find a good way to practise', text: 'What are some effective exercises for improving fluency and managing long pauses?' },
  ] } },
  methods: {
    renderMarkdown (value) { return DOMPurify.sanitize(markdown.render(value)) },
    scrollToLatest () { this.$nextTick(() => { const el = this.$refs.scroll; if (el) el.scrollTop = el.scrollHeight }) },
    usePrompt (text) { if (this.busy || this.failed) return; this.draft = text; this.$nextTick(() => this.$refs.input && this.$refs.input.focus()) },
    onKeydown (event) { if (event.key === 'Enter' && !event.shiftKey && !event.isComposing) { event.preventDefault(); this.send() } },
    async send () { const text = this.draft.trim(); if (!text || this.busy || this.failed) return; this.messages.push({ id: ++this.sequence, role: 'user', content: text }); this.draft = ''; await this.requestReply() },
    async requestReply () {
      if (this.busy || !this.messages.length || this.messages[this.messages.length - 1].role !== 'user') return
      this.busy = true; this.error = ''; this.failed = false; this.scrollToLatest()
      const controller = new AbortController(); this.activeRequest = controller
      const timeout = setTimeout(() => controller.abort(), 90000)
      let history = this.messages.slice(-21).map(({ role, content }) => ({ role, content: content.slice(0, 4000) }))
      while (history.length > 1 && history.reduce((sum, item) => sum + item.content.length, 0) > 24000) history = history.slice(2)
      try {
        const response = await fetch('/api/speaking/consult', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ exam: this.exam, messages: history }), signal: controller.signal })
        let data; try { data = await response.json() } catch (_) { throw new Error('The server returned an unexpected response. Please try again.') }
        if (!response.ok) throw new Error(typeof data.detail === 'string' ? data.detail : 'Please check the connection and try again.')
        if (typeof data.reply !== 'string' || !data.reply.trim()) throw new Error('The assistant returned an empty response. Please try again.')
        if (this.activeRequest !== controller) return
        this.messages.push({ id: ++this.sequence, role: 'assistant', content: data.reply.trim() }); this.scrollToLatest()
      } catch (error) {
        if (this.activeRequest !== controller) return
        this.failed = true; this.error = error.name === 'AbortError' ? 'The request took too long. Check your connection and try again.' : (error.message || 'Please check the connection and try again.'); this.scrollToLatest()
      } finally { clearTimeout(timeout); if (this.activeRequest === controller) { this.activeRequest = null; this.busy = false } }
    },
    retry () { if (!this.busy && this.failed) this.requestReply() },
    editFailed () { if (this.busy || !this.failed) return; const last = this.messages[this.messages.length - 1]; if (last && last.role === 'user') { this.draft = last.content; this.messages.pop() } this.failed = false; this.error = ''; this.$nextTick(() => this.$refs.input && this.$refs.input.focus()) },
    newChat () { if ((this.messages.length || this.draft.trim()) && !window.confirm('Start a new conversation? The current chat will be cleared.')) return; if (this.activeRequest) this.activeRequest.abort(); this.activeRequest = null; this.busy = false; this.messages = []; this.draft = ''; this.error = ''; this.failed = false; this.$nextTick(() => this.$refs.input && this.$refs.input.focus()) },
  },
  beforeDestroy () { if (this.activeRequest) this.activeRequest.abort(); this.activeRequest = null },
}
</script>

<style scoped src="./prep-chat.css"></style>
